public static void basePriceCalcJobMonitorQueryRun(SysGuid _sessionGuid, METBatchLogOperation _operation)
{
    if (!_sessionGuid)
    {
        warning("Session GUID is empty.");
        return;
    }

    UserConnection              userCon = new UserConnection();
    GUPBasePriceCalcItemTask    taskRec;
    GUPBasePriceCalcItemTask    taskJoin;
    GUPVendPriceAdmTrans        vendTrans;
    GUPVendPriceAdmTable        vendTable;
    GUPItemBasePrice            itemBasePrice;
    GUPItemBasePrice            basePriceJoin;
    InventItemPriceSim          sim;
    InventItemPrice             inventItemPrice;

    try
    {
        taskRec.setConnection(userCon);
        vendTrans.setConnection(userCon);
        itemBasePrice.setConnection(userCon);
        sim.setConnection(userCon);
        inventItemPrice.setConnection(userCon);

        select count(RecId) from taskRec
          where taskRec.SessionGuid == _sessionGuid;

        int64 taskCount = taskRec.RecId;

        select count(RecId) from vendTrans
          where vendTrans.IsDirty == GUPNoYesMarked::Yes
          exists join vendTable
              where vendTable.JournalNum == vendTrans.JournalNum
                 && vendTable.Status     == GUPDisabledEnabled::Enabled
          exists join taskJoin
              where taskJoin.ItemId      == vendTrans.ItemNum
                 && taskJoin.SessionGuid == _sessionGuid;

        int64 dirtyCount = vendTrans.RecId;

        select count(RecId) from vendTrans
          exists join vendTable
              where vendTable.JournalNum == vendTrans.JournalNum
                 && vendTable.Status     == GUPDisabledEnabled::Enabled
          exists join taskJoin
              where taskJoin.ItemId      == vendTrans.ItemNum
                 && taskJoin.SessionGuid == _sessionGuid;

        int64 dirtyTotal = vendTrans.RecId;

        select count(RecId) from itemBasePrice
          where itemBasePrice.OperationGuid == _sessionGuid;

        int64 basePriceTotal = itemBasePrice.RecId;

        select count(RecId) from itemBasePrice
          where itemBasePrice.OperationGuid == _sessionGuid
             && itemBasePrice.IsExpired      == NoYes::Yes;

        int64 basePriceExpired = itemBasePrice.RecId;

        select count(RecId) from itemBasePrice
          where itemBasePrice.OperationGuid                == _sessionGuid
             && itemBasePrice.METItemPriceActivationStatus == METItemPriceActivationStatus::None;

        int64 statusNone = itemBasePrice.RecId;

        select count(RecId) from itemBasePrice
          where itemBasePrice.OperationGuid                == _sessionGuid
             && itemBasePrice.METItemPriceActivationStatus == METItemPriceActivationStatus::Completed;

        int64 statusCompleted = itemBasePrice.RecId;

        select count(RecId) from itemBasePrice
          where itemBasePrice.OperationGuid                == _sessionGuid
             && itemBasePrice.METItemPriceActivationStatus == METItemPriceActivationStatus::Failed;

        int64 statusFailed = itemBasePrice.RecId;

        select count(RecId) from itemBasePrice
          where itemBasePrice.OperationGuid                == _sessionGuid
             && itemBasePrice.METItemPriceActivationStatus == METItemPriceActivationStatus::Skipped;

        int64 statusSkipped = itemBasePrice.RecId;

        select count(RecId) from sim
          exists join basePriceJoin
              where basePriceJoin.RecId         == sim.METGUPItemBasePriceId
                 && basePriceJoin.OperationGuid == _sessionGuid;

        int64 simCount = sim.RecId;

        select count(RecId) from inventItemPrice
          exists join basePriceJoin
              where basePriceJoin.RecId         == inventItemPrice.METGUPItemBasePriceId
                 && basePriceJoin.OperationGuid == _sessionGuid;

        int64 activatedCount = inventItemPrice.RecId;

        str nl   = '\n';
        str line = '------------------------------------------------------------';

        str assessCalc;
        if (basePriceTotal == 0 && taskCount == 0)
        {
            assessCalc = '  Calculation   : NOT STARTED or invalid GUID';
        }
        else if (taskCount > 0)
        {
            assessCalc = strFmt('  Calculation   : IN PROGRESS  (%1 items queued)', taskCount);
        }
        else
        {
            assessCalc = '  Calculation   : COMPLETE';
        }

        str assessDirty;
        if (dirtyCount > 0)
        {
            assessDirty = strFmt('  Dirty cleanup : IN PROGRESS  (%1 dirty records remain)', dirtyCount);
        }
        else if (dirtyTotal > 0)
        {
            assessDirty = '  Dirty cleanup : COMPLETE';
        }
        else
        {
            assessDirty = '  Dirty cleanup : NOT REACHED or no dirty data in scope';
        }

        str assessActivation;
        if (basePriceTotal == 0)
        {
            assessActivation = '  Base prices   : NOT YET CREATED';
        }
        else if (statusNone > 0 || statusFailed > 0)
        {
            assessActivation = strFmt('  MET activation: PENDING  (%1 None, %2 Failed)', statusNone, statusFailed);
        }
        else
        {
            assessActivation = '  MET activation: COMPLETE';
        }

        str output =
          line                                                                                    + nl +
          '  Base Price Calculation Monitor'                                                      + nl +
          strFmt('  Operation : %1', enum2Str(_operation))                                       + nl +
          strFmt('  Session   : %1', _sessionGuid)                                               + nl +
          strFmt('  Queried   : %1', DateTimeUtil::toStr(DateTimeUtil::utcNow()))                 + nl +
          line                                                                                    + nl +
          '[PHASE 1-3  Calculation tasks  (GUPBasePriceCalcItemTask)]'                           + nl +
          strFmt('  Items queued        : %1  (0 = complete or cleanup ran)', taskCount)          + nl +
          '[PHASE 4  Dirty data  (GUPVendPriceAdmTrans)]'                                        + nl +
          strFmt('  Still dirty         : %1', dirtyCount)                                       + nl +
          strFmt('  Cleared             : %1', dirtyTotal - dirtyCount)                          + nl +
          strFmt('  Total in scope      : %1', dirtyTotal)                                       + nl +
          '[PHASE 5  Base prices  (GUPItemBasePrice)]'                                           + nl +
          strFmt('  Created this session: %1', basePriceTotal)                                   + nl +
          strFmt('  Expired             : %1', basePriceExpired)                                 + nl +
          '[PHASE 6  MET activation status  (GUPItemBasePrice)]'                                 + nl +
          strFmt('  None      (pending) : %1', statusNone)                                       + nl +
          strFmt('  Completed           : %1', statusCompleted)                                  + nl +
          strFmt('  Failed              : %1', statusFailed)                                     + nl +
          strFmt('  Skipped             : %1', statusSkipped)                                    + nl +
          '[PHASE 6  Cost price sims  (InventItemPriceSim)]'                                     + nl +
          strFmt('  Pending sims        : %1', simCount)                                         + nl +
          '[PHASE 6  Activated prices  (InventItemPrice)]'                                       + nl +
          strFmt('  Activated           : %1', activatedCount)                                   + nl +
          line                                                                                    + nl +
          '[STATUS ASSESSMENT]'                                                                   + nl +
          assessCalc                                                                              + nl +
          assessDirty                                                                             + nl +
          assessActivation                                                                        + nl +
          line;

        info(output);
    }
    finally
    {
        userCon.finalize();
    }
}

public static void run(METBatchMonitoringLog _log)
{
    if (!_log)
    {
        warning("Incorrectly called without monitoring log buffer");
        return;
    }

    switch (_log.Operation)
    {
        case METBatchLogOperation::BasePriceCalculation:
        case METBatchLogOperation::BasePriceActivation_ActivateCurrentPrice:
            METBatchMonitoringLogProgressQuery::basePriceCalcJobMonitorQueryRun(_log.SessionGuid, _log.Operation);
            break;
        default:
            warning("No monitoring query implemented for this type of batch job.");
            break;
    }
}
